INSERT INTO `artifacts` VALUES (1,'ART-1786079504749',1,2,NULL,2,'market_research','note市場・需要調査（上位テーマ候補抽出）','note上で初心者が参入しやすく販売につながりやすいと考えられる上位10テーマクラスタを抽出し、それぞれについてnote内の需要指標（推定）、外部検索需要概況（推定）、競合密度評価、初心者向けの切り口、参考となる有料noteの参照URL（タグ検索などの代表リンク）を提示しました。※本レポートは、2024年6月までの公開知見と一般的市場動向に基づく推定を含みます。noteプラットフォームのリアルタイムスクレイピングは実行していないため、個別有料記事の現状データはタグ検索や代表例URLを参照する形で示しています。事実と推測は明示しています（references参照）。','{\n  \"status\": \"completed\",\n  \"manager\": \"SUN_TZU\",\n  \"summary\": \"note上で初心者が参入しやすく販売につながりやすいと考えられる上位10テーマクラスタを抽出し、それぞれについてnote内の需要指標（推定）、外部検索需要概況（推定）、競合密度評価、初心者向けの切り口、参考となる有料noteの参照URL（タグ検索などの代表リンク）を提示しました。※本レポートは、2024年6月までの公開知見と一般的市場動向に基づく推定を含みます。noteプラットフォームのリアルタイムスクレイピングは実行していないため、個別有料記事の現状データはタグ検索や代表例URLを参照する形で示しています。事実と推測は明示しています（references参照）。\",\n  \"market_size\": \"不明（noteのプラットフォーム全体の有料コンテンツ市場規模の公開数値は限定的。外部推定は可能だが本報告では明確な一次データ取得を行っていないため「不明」と表記）\",\n  \"growth_rate\": \"不明（note自体の売上成長率等の公開統計は限定的。コンテンツ有料化・サブスク化の市場トレンドは上昇傾向と推定）\",\n  \"target_users\": [\n    {\n      \"persona\": \"副業志望の20-40代会社員\",\n      \"needs\": \"短期間で実践可能な収益化ノウハウ、テンプレ／ステップ化された手順、低初期費用\"\n    },\n    {\n      \"persona\": \"個人クリエイター（写真・動画・イラスト）\",\n      \"needs\": \"作品の販売方法、ファン化、noteの使い分けノウハウ\"\n    },\n    {\n      \"persona\": \"転職・キャリア改善を目指す社会人\",\n      \"needs\": \"履歴書/面接テンプレ、ポートフォリオ作成、業界別の転職ノウハウ\"\n    },\n    {\n      \"persona\": \"資格試験・語学学習者\",\n      \"needs\": \"合格ノウハウ、短期集中勉強法、模試・問題集テンプレ\"\n    },\n    {\n      \"persona\": \"健康/自己改善に関心がある層\",\n      \"needs\": \"ダイエット/メンタル改善の実践手順、記録テンプレート\"\n    }\n  ],\n  \"competitors\": [\n    {\n      \"name\": \"pixivFANBOX\",\n      \"description\": \"クリエイター向け定期課金プラットフォーム（主にイラスト・漫画など）\"\n    },\n    {\n      \"name\": \"Patreon（国外）/日本の類似サブスクプラットフォーム\",\n      \"description\": \"ファン課金型の長期収益化向け\"\n    },\n    {\n      \"name\": \"Zenn / Qiita\",\n      \"description\": \"技術・IT系コンテンツに強く、ノウハウ販売や有料記事も存在\"\n    },\n    {\n      \"name\": \"Udemy / スキルシェア系（オンライン講座）\",\n      \"description\": \"長尺の学習教材販売で競合\"\n    },\n    {\n      \"name\": \"note内の人気個人クリエイター群\",\n      \"description\": \"ジャンルごとの強力な個人オピニオンリーダーが競合\"\n    }\n  ],\n  \"strengths\": [\n    \"noteは国内知名度が高く、文章ベースで販売・ファン化がしやすい\",\n    \"タグ検索・ランキングによる発見経路があり初心者でも露出機会を作りやすい（推定）\",\n    \"無料と有料を組み合わせた導線（先出し無料＋深掘り有料）が機能しやすい\"\n  ],\n  \"weaknesses\": [\n    \"プラットフォーム上の有料記事はジャンルによって既に競合が強い領域がある\",\n    \"note単独での巨大流入は限定的なため外部流入（SNS・検索）施策が必須（推測）\"\n  ],\n  \"opportunities\": [\n    \"テンプレ化・チェックリスト化・ケーススタディの形式は初心者でも商品化しやすい\",\n    \"ロングテール／地域特化／狭い業界向けノウハウは競合が薄く参入余地あり（推測）\"\n  ],\n  \"risks\": [\n    \"人気テーマは価格競争や無料化により単価低下のリスク\",\n    \"プラットフォームポリシーや手数料変更のリスク（不確定）\"\n  ],\n  \"pricing\": [\n    {\n      \"cluster\": \"副業・稼ぎ方\",\n      \"typical_price_range_jpy\": \"¥300〜¥5,000（単体記事）／月額サブスク¥300〜¥2,000\",\n      \"basis\": \"note上の一般的な販売例（推定）\"\n    },\n    {\n      \"cluster\": \"ブログ／アフィリエイト\",\n      \"typical_price_range_jpy\": \"¥500〜¥5,000\",\n      \"basis\": \"テンプレ＋個別相談をセットにするケースが多い（推定）\"\n    },\n    {\n      \"cluster\": \"SNS／YouTube運用\",\n      \"typical_price_range_jpy\": \"¥500〜¥4,000\",\n      \"basis\": \"実践型チェックリストやスクリプト化が売れやすい（推定）\"\n    },\n    {\n      \"cluster\": \"投資・暗号資産\",\n      \"typical_price_range_jpy\": \"¥500〜¥10,000\",\n      \"basis\": \"投資成績を出せる場合に高単価化しやすい（推定・注意事項あり）\"\n    },\n    {\n      \"cluster\": \"資格・学習\",\n      \"typical_price_range_jpy\": \"¥300〜¥3,000\",\n      \"basis\": \"問題集・暗記シート・勉強法のテンプレ化が中心（推定）\"\n    }\n  ],\n  \"keywords\": [\n    \"副業\",\n    \"ブログ収益化\",\n    \"Twitter運用\",\n    \"転職活動\",\n    \"プログラミング学習\",\n    \"株式投資\",\n    \"暗号資産\",\n    \"ダイエット法\",\n    \"恋愛テクニック\",\n    \"写真編集\"\n  ],\n  \"success_cases\": [\n    {\n      \"case\": \"テンプレ型副業ノウハウで数千DL・月数十万円\",\n      \"fact_vs_guess\": \"推測（公開の個別収益データを直接参照しておらず、複数報告事例の傾向に基づく）\",\n      \"notes\": \"テンプレ＋手順化で初心者が再現可能と感じやすいコンテンツは売れやすい傾向\"\n    },\n    {\n      \"case\": \"SNS運用ノウハウで有料フォロワー化に成功\",\n      \"fact_vs_guess\": \"推測\",\n      \"notes\": \"実例として、短期間で再現可能な運用ルール提供が有効\"\n    }\n  ],\n  \"failure_cases\": [\n    {\n      \"case\": \"一般論だけの薄い有料記事は販売に繋がらず低評価\",\n      \"fact_vs_guess\": \"事実（プラットフォームでの購入者レビュー傾向に基づく一般傾向）\",\n      \"notes\": \"独自性・再現性が無いコンテンツは購買に繋がりにくい\"\n    },\n    {\n      \"case\": \"高価格だが実績提示が乏しい投資noteの炎上／返金要求\",\n      \"fact_vs_guess\": \"事実および推測（投資領域の過去の炎上事例は確認されているが本レポートで個別事例の直接検証は行っていない）\",\n      \"notes\": \"投資系は情報の正確性・免責の整備が必須\"\n    }\n  ],\n  \"references\": [\n    {\n      \"title\": \"note（プラットフォーム）\",\n      \"url\": \"https://note.com/\",\n      \"type\": \"プラットフォーム（事実）\"\n    },\n    {\n      \"title\": \"note について（公式）\",\n      \"url\": \"https://about.note.com/\",\n      \"type\": \"公式情報（事実）\"\n    },\n    {\n      \"title\": \"Google キーワードプランナー\",\n      \"url\": \"https://ads.google.com/home/tools/keyword-planner/\",\n      \"type\": \"外部検索需要推定ツール（参照推奨、推測に使用可能）\"\n    },\n    {\n      \"title\": \"SimilarWeb - note.com（トラフィック傾向参照）\",\n      \"url\": \"https://www.similarweb.com/website/note.com/\",\n      \"type\": \"外部サイトトラフィック指標（参考、推測）\"\n    },\n    {\n      \"title\": \"過去のnote関連の公開記事・インタビュー等（各種メディア）\",\n      \"url\": \"https://www.google.com/search?q=note+%E3%83%8E%E3%83%BC%E3%83%88+%E6%9C%80%E9%80%B2\",\n      \"type\": \"一般的な情報収集経路（参考）\"\n    },\n    {\n      \"title\": \"注記：本レポートのデータ性について\",\n      \"url\": \"about:blank\",\n      \"type\": \"本レポートは2024年6月までの公開知見と一般市場動向に基づく推定を含む。noteのリアルタイム内部データ取得は行っていないため、個別有料記事の最新実績はタグ検索やプラットフォーム内での確認を推奨（事実・推測を区別）。\"\n    }\n  ],\n  \"confidence\": 80,\n  \"competitor_analysis_notes\": \"上記『competitors』はnoteと機能・マネタイズ面で競合し得るサービス群。各競合の強み（例：FANBOXは継続課金強者、Udemyは長尺教材に強い等）は一般的知見に基づく推定。\",\n  \"top10_theme_clusters\": [\n    {\n      \"cluster_id\": 1,\n      \"name\": \"副業・稼ぎ方（実践型）\",\n      \"description\": \"短期で始められる副業（クラウドソーシング、転売、デジタルプロダクト販売、SNS運用等）の実践手順やテンプレ。低初期費用で再現性のある手順が購入に繋がりやすい。\",\n      \"demand_indicators_note_internal\": {\n        \"paid_articles_estimate\": \"高（タグ内の有料記事多数、推定で数百〜千以上）\",\n        \"avg_likes_estimate\": \"中〜高（成功事例や数字を出した記事は高評価）\",\n        \"comment_trend\": \"質問・体験共有コメントが多く、追記要求が発生しやすい（推定）\"\n      },\n      \"external_search_estimate\": {\n        \"search_volume_category\": \"高\",\n        \"examples_keywords_and_estimates\": [\n          {\n            \"keyword\": \"副業\",\n            \"monthly_search_estimate\": \">100,000（概算カテゴリ）\"\n          },\n          {\n            \"keyword\": \"在宅ワーク\",\n            \"monthly_search_estimate\": \"10,000〜100,000（概算カテゴリ）\"\n          }\n        ]\n      },\n      \"competition_density\": \"高\",\n      \"beginner_entry_angles\": [\n        \"特定の職業・年齢層向けに絞る（例：会社員×育児中の親向け副業）\",\n        \"テンプレ＋チェックリスト化して再現性を担保\",\n        \"初期0円の手法に絞ったケーススタディ＋成功/失敗の数値公開\"\n      ],\n      \"examples\": [\n        {\n          \"title\": \"（サンプル）未経験から3ヶ月で月5万円を目指す副業ロードマップ\",\n          \"format\": \"有料単体note + PDFテンプレ付き\",\n          \"price_jpy\": \"¥1,200\",\n          \"publish_date\": \"不明（代表サンプル）\",\n          \"url\": \"https://note.com/search?q=%E5%89%AF%E6%A5%AD\"\n        },\n        {\n          \"title\": \"（サンプル）メルカリ転売0→10万円/月達成マニュアル\",\n          \"format\": \"有料単体note\",\n          \"price_jpy\": \"¥800\",\n          \"publish_date\": \"不明（代表サンプル）\",\n          \"url\": \"https://note.com/search?q=%E5%BB%95%E8%B2%A9\"\n        },\n        {\n          \"title\": \"（サンプル）スキル販売（クラウドワークス）で月3万円稼ぐ案件テンプレ\",\n          \"format\": \"有料シリーズ / 定期更新\",\n          \"price_jpy\": \"月額¥500\",\n          \"publish_date\": \"不明（代表サンプル）\",\n          \"url\": \"https://note.com/search?q=%E3%82%AF%E3%83%A9%E3%82%A6%E3%83%89%E3%82%B5%E3%83%BC%E3%83%93%E3%82%B9\"\n        }\n      ]\n    },\n    {\n      \"cluster_id\": 2,\n      \"name\": \"ブログ／アフィリエイト収益化\",\n      \"description\": \"ブログ開設からSEO・収益化までのテンプレ、記事テンプレ、キーワード選定法、収益報告など。再現性のある手順が重要。\",\n      \"demand_indicators_note_internal\": {\n        \"paid_articles_estimate\": \"高（ブログ系の有料noteは多い）\",\n        \"avg_likes_estimate\": \"中\",\n        \"comment_trend\": \"具体的な添削依頼や追加質問が発生しやすい（推定）\"\n      },\n      \"external_search_estimate\": {\n        \"search_volume_category\": \"高\",\n        \"examples_keywords_and_estimates\": [\n          {\n            \"keyword\": \"ブログ 収益化\",\n            \"monthly_search_estimate\": \"10,000〜100,000（概算カテゴリ）\"\n          },\n          {\n            \"keyword\": \"アフィリエイト 始め方\",\n            \"monthly_search_estimate\": \"10,000〜50,000（概算カテゴリ）\"\n          }\n        ]\n      },\n      \"competition_density\": \"高\",\n      \"beginner_entry_angles\": [\n        \"特定ジャンル（美容/育児/副業など）に特化した記事テンプレ配布\",\n        \"SEOで成果を出した実績の小分け化（例：1キーワード攻略法）\",\n        \"はじめてのブログ立ち上げチェックリスト＋画像付き手順\"\n      ],\n      \"examples\": [\n        {\n          \"title\": \"（サンプル）雑記ブログで月3万円を作る記事テンプレ30選\",\n          \"format\": \"有料note + テンプレDL\",\n          \"price_jpy\": \"¥1,500\",\n          \"publish_date\": \"不明\",\n          \"url\": \"https://note.com/search?q=%E3%83%96%E3%83%AD%E3%82%B0+%E5%8F%8E%E7%9B%8A%E5%8C%96\"\n        },\n        {\n          \"title\": \"（サンプル）アフィリエイト案件選定リスト（使い方ガイド付き）\",\n          \"format\": \"有料単体note\",\n          \"price_jpy\": \"¥800\",\n          \"publish_date\": \"不明\",\n          \"url\": \"https://note.com/search?q=%E3%82%A2%E3%83%95%E3%82%A3%E3%83%AA%E3%82%A8%E3%82%A4%E3%83%88\"\n        },\n        {\n          \"title\": \"（サンプル）WordPress初期設定＋収益化チェックリスト\",\n          \"format\": \"有料PDF付note\",\n          \"price_jpy\": \"¥1,000\",\n          \"publish_date\": \"不明\",\n          \"url\": \"https://note.com/search?q=WordPress+%E3%82%BB%E3%83%83%E3%83%88%E3%82%A2%E3%83%83%E3%83%97\"\n        }\n      ]\n    },\n    {\n      \"cluster_id\": 3,\n      \"name\": \"SNS（Twitter/Instagram）・YouTube運用\",\n      \"description\": \"アカウント設計、発信テンプレ、マネタイズ手順、アルゴリズムに合わせた投稿スケジュールなどの具体的ノウハウ。\",\n      \"demand_indicators_note_internal\": {\n        \"paid_articles_estimate\": \"中〜高\",\n        \"avg_likes_estimate\": \"中\",\n        \"comment_trend\": \"フォロワー獲得に関する相談・実践報告が多い（推定）\"\n      },\n      \"external_search_estimate\": {\n        \"search_volume_category\": \"高\",\n        \"examples_keywords_