--
-- Table structure for table `tasks`
--

DROP TABLE IF EXISTS `tasks`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tasks` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `task_code` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `project_id` bigint unsigned NOT NULL,
  `workflow_run_id` bigint unsigned DEFAULT NULL,
  `parent_task_id` bigint unsigned DEFAULT NULL,
  `assigned_agent_id` bigint unsigned NOT NULL,
  `next_agent_id` bigint unsigned DEFAULT NULL,
  `task_type` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `title` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `goal` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `instructions` longtext COLLATE utf8mb4_unicode_ci,
  `constraints_json` json DEFAULT NULL,
  `required_outputs_json` json DEFAULT NULL,
  `status` enum('pending','running','reviewing','needs_revision','waiting_information','completed','failed','cancelled') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `quality_threshold` decimal(5,2) NOT NULL DEFAULT '80.00',
  `revision_count` int unsigned NOT NULL DEFAULT '0',
  `max_revisions` int unsigned NOT NULL DEFAULT '3',
  `due_at` datetime DEFAULT NULL,
  `started_at` datetime DEFAULT NULL,
  `completed_at` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `task_code` (`task_code`),
  KEY `fk_tasks_workflow_run` (`workflow_run_id`),
  KEY `fk_tasks_parent` (`parent_task_id`),
  KEY `fk_tasks_next_agent` (`next_agent_id`),
  KEY `idx_tasks_status` (`status`),
  KEY `idx_tasks_assigned_agent` (`assigned_agent_id`),
  KEY `idx_tasks_project` (`project_id`),
  CONSTRAINT `fk_tasks_assigned_agent` FOREIGN KEY (`assigned_agent_id`) REFERENCES `agents` (`id`),
  CONSTRAINT `fk_tasks_next_agent` FOREIGN KEY (`next_agent_id`) REFERENCES `agents` (`id`),
  CONSTRAINT `fk_tasks_parent` FOREIGN KEY (`parent_task_id`) REFERENCES `tasks` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_tasks_project` FOREIGN KEY (`project_id`) REFERENCES `projects` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_tasks_workflow_run` FOREIGN KEY (`workflow_run_id`) REFERENCES `workflow_runs` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=14 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
