/*!40000 ALTER TABLE `tasks` DISABLE KEYS */;
INSERT INTO `tasks` VALUES (1,'TSK-TEST-001',1,NULL,NULL,1,NULL,'manager_analysis','レオナルド初回テスト','依頼内容を分析してタスク分解する','経験0・フォロワー0・人脈0から、noteで売れるテーマを探したい',NULL,NULL,'running',80.00,0,3,NULL,'2026-08-07 11:56:55',NULL,'2026-08-07 11:56:55','2026-08-07 11:56:55'),(2,'TSK-1786072536696-1',1,NULL,NULL,2,2,'market_research','note市場・需要調査（上位テーマ候補抽出）','note上で『初心者でも販売可能性が高いテーマ群』を10件程度抽出し、需要と競合の概況を提示する','note内の有料記事・有料フォロワー獲得実績・人気タグ・ランキングを調査し、次をレポートしてください。1) 売れている/購買に繋がりやすいテーマクラスタを10件。2) 各クラスタの需要指標（note内の有料記事件数・いいね数・コメント傾向）、外部検索需要の推定（関連キーワードの月間検索量目安）、競合密度（高/中/低）を提示。3) 初心者が参入しやすい切り口（例：ビギナー向けのニッチ角度／テンプレ化できるノウハウ等）を各クラスタごとに示す。4) 実例（有料noteのタイトルと販売形式、価格帯、公開日）を3件ずつ示す。','[\"日本語のデータを優先\", \"初期費用ゼロを前提の参入可能性を評価\", \"外部有料ツール使用は可だが結果の出典を明記\"]','[\"トップ10のテーマクラスタ一覧（各クラスタに説明文）\", \"需要指標の表（note内指標／外部検索推定）\", \"競合密度評価（高/中/低）\", \"参入しやすい切り口の提案（各クラスタ）\", \"参考となる有料noteのURLと簡易メタ情報\"]','completed',80.00,0,3,NULL,NULL,'2026-08-07 14:15:22','2026-08-07 12:15:47','2026-08-07 14:15:22'),(3,'TSK-1786072536696-2',1,NULL,NULL,2,3,'competitive_analysis','競合コンテンツ分析（候補クラスタの深掘り）','タスク1で抽出した上位クラスタのうち、上位3クラスタをより詳細に分析し、勝ち筋（差別化ポイント）を見つける','上位3クラスタを選定し、それぞれについて以下を作成する。1) 上位10の有料noteの共通点（構成、目次、価格、本文量、サンプルの有無、付加物の有無）。2) 読者が金を払う決定要因とされる要素の抽出（テンプレ・実践導線・ワークシートなど）。3) 差別化の余地（未充足ニーズ／初心者が提供できる具体案）を3案提示。4) 競合が弱いキーワード／切り口のリスト化。','[\"事実と推測を区別して記載\", \"参照リンクとスクリーンショット（可能なら）を添付\"]','[\"クラスタごとの競合分析レポート（表形式で要点）\", \"差別化案の箇条書き（実行可能性付き）\", \"優先的に狙うべきキーワードリスト\"]','pending',80.00,0,3,NULL,NULL,NULL,'2026-08-07 12:15:47','2026-08-07 12:15:47'),(4,'TSK-1786072536696-3',1,NULL,NULL,2,3,'keyword_research','SEO／検索キーワード調査（商用キーワード抽出）','note外検索経路（Google等）からの導線となる商用キーワードとロングテールを抽出し、優先順位をつける','タスク1〜2のクラスタを元に、商用意図の高いキーワード（購入意図がある検索語）とロングテールを抽出。各キーワードに対して月間検索推定、関連語、競合の強さ（高/中/低）、想定のCTR・CVRの粗い目安を示してください。特に『初心者でも上位表示が現実的なロングテール』を優先して提示すること。','[\"無料で参照可能なツール情報を優先して出典を明記\", \"定量データがない場合は根拠つきの推定を行う\"]','[\"優先キーワードリスト（上位30）とクラスタ対応表\", \"上位10キーワードの詳細（検索量推定・競合度・狙い目の根拠）\", \"推奨ターゲットキーワード（3〜5）\"]','pending',80.00,0,3,NULL,NULL,NULL,'2026-08-07 12:15:47','2026-08-07 12:15:47'),(5,'TSK-1786072536696-4',1,NULL,NULL,3,3,'persona_design','ターゲットペルソナ設計（初心者向け）','経験0・フォロワー0の状態でも購買につながりやすい読者像（ペルソナ）を3つ作成し、最適な1つを推奨する','タスク1〜3の出力を踏まえて、購買に結びつきやすいペルソナを3種作成してください（各ペルソナは名前・年齢層・職業・悩み・決済力・情報接触チャネル・期待するコンテンツ形式を含む）。それぞれに対して『なぜこのペルソナが少ないリソースでも買いやすいか』の根拠を示し、最終的に最優先で狙う1ペルソナを選定して理由を述べること。','[\"ペルソナは日本国内ユーザー想定\", \"データが弱い部分は推定と明記する\"]','[\"3つのペルソナ詳細シート\", \"推奨ペルソナ1つと選定理由（短文）\"]','completed',80.00,0,3,NULL,NULL,'2026-08-07 14:20:31','2026-08-07 12:15:47','2026-08-07 14:20:31'),(6,'TSK-1786072536696-5',1,NULL,NULL,3,4,'product_concept','商品コンセプト設計（有料noteの企画）','選定ペルソナ向けに、再現性が高く販売可能なnoteの商品コンセプトを3案作る（価格・USP・提供物を明確化）','推奨ペルソナ向けに、次のフォーマットで3案作成。1) 商品名、2) 価格帯（想定）、3) 商品タイプ（単品／シリーズ／テンプレ／ワークブック等）、4) USP（初心者が勝てる理由）、5) 販売導線（フリーペーパー→有料noteなど）、6) 必要原稿量・付帯素材、7) 最短でMVPを作るための最小実行手順（週単位）。各案に対して期待される売上粗見積もり（仮定に基づく）とリスクを記載する。','[\"初期リソースを抑える設計を優先\", \"価格は日本のnote相場感を参考に\"]','[\"3つの企画案（上記フォーマット）\", \"各案の期待売上レンジと主なリスク\"]','pending',80.00,0,3,NULL,NULL,NULL,'2026-08-07 12:15:47','2026-08-07 12:15:47'),(7,'TSK-1786072536696-6',1,NULL,NULL,3,4,'content_plan','ローンチ用コンテンツ計画（記事シリーズ＋導線）','選定した商品案に対して、最初の8本〜12本程度のnote（無料＋有料）の編集カレンダーと導線を作る','MVP販売に向けたコンテンツスケジュール（週次または隔週）とそれぞれの記事の役割（集客／教育／販売）、フリーペーパーの誘導設計、オファー設計（割引、早割、特典）を作成。さらにローンチ初期のKPI目標（例：PV、メーリングリスト登録、購入率）を示すこと。記事ごとに想定キーワードと目安文字数（日本語）を付記する。','[\"初期は無料集客を重視（広告費0を想定）\", \"制作リソースを週数時間レベルに抑えられる設計\"]','[\"8〜12本の編集カレンダー（タイトル案＋目的＋キーワード＋文字数目安）\", \"フリー→有料への導線図（ステップ）\", \"初期KPI一覧と目標値（仮）\"]','pending',80.00,0,3,NULL,NULL,NULL,'2026-08-07 12:15:47','2026-08-07 12:15:47'),(8,'TSK-1786072536696-7',1,NULL,NULL,4,4,'headline_and_outline','記事タイトル案と本文構成作成（上位候補）','ローンチで使える魅力的なタイトル案を10個と、優先3本の詳細な記事構成（見出し・リード・導入・CTA）を作る','タスク6の編集カレンダー上位3記事について、SEOキーワードを組み込んだクリックしやすいタイトルを10案ずつ作成し、各記事の詳細構成（見出しH1〜H3相当、各段落の要点、想定文字数、読者の抵抗を下げる導入文例、CTA文例）を作成してください。タイトルは販売用（有料note）と集客用（無料note）で分けて提示すること。','[\"日本語で自然な表現\", \"誇張表現や虚偽を避ける\"]','[\"各記事につき10のタイトル案（販売用／無料用の区分）\", \"3記事分の詳細構成（見出し＋段落要点＋CTA）\"]','completed',80.00,0,3,NULL,NULL,'2026-08-07 14:24:19','2026-08-07 12:15:47','2026-08-07 14:24:19'),(9,'TSK-1786072536696-8',1,NULL,NULL,4,5,'article_draft','有料noteの本文ドラフト（1本目・MVP）','購入につながる完成度の高い有料note本文のドラフトを作成する（MVP版）','タスク7で選ばれた最優先の有料記事構成に基づき、実際に販売できるレベルの本文を作成してください。要件：読者に実践可能なステップを提供、ワークシートやテンプレがある場合は本文内に貼付（サンプルを作成）、CTAは明確に。目安文字数は商品コンセプトに合わせて指定する（例：有料note 3,000〜8,000字相当）。出典や根拠がある場合は注記を付けること。','[\"事実と推測を明確に分ける\", \"盗作禁止（引用は出典明記）\"]','[\"有料note本文ドラフト（日本語）\", \"本文内で使う付帯素材（テンプレ／チェックリスト等）\"]','pending',85.00,0,3,NULL,NULL,NULL,'2026-08-07 12:15:47','2026-08-07 12:15:47'),(10,'TSK-1786072536696-9',1,NULL,NULL,5,6,'design','サムネイル・アイキャッチ設計（販売用）','有料noteの購買を高めるサムネイル案と、AI画像生成プロンプトを3案作る','タスク8のタイトルと本文のトーンに合わせて、noteの一覧で目立つサムネイルを3案作成。各案に対して: 1) キャッチテキスト案（短い副題含む）、2) 色・配色パターン、3) フォントの方向性、4) 画像生成用プロンプト（英日両方あると可）、5) サムネイルの簡易モック（説明で可）を提示。低リソースで制作できる方法（Canvaのテンプレで再現可能な指示）も記載する。','[\"サムネはモバイル表示での視認性を優先\", \"過度な誇張表現は避ける\"]','[\"3案のサムネイル仕様書（プロンプト含む）\", \"Canva等で再現するための手順メモ\"]','completed',80.00,0,3,NULL,NULL,NULL,'2026-08-07 12:15:47','2026-08-07 14:34:58'),(11,'TSK-1786072536696-10',1,NULL,NULL,6,7,'marketing','初動集客・ローンチ施策（フォロワー0から始める）','フォロワー0・人脈0の状態で初動を作るための具体的なSNS／note内施策と初週〜初月の実行プランを作る','広告費ゼロ前提の施策を中心に、X(Twitter)、Threads、noteタグ、はてなブックマーク、関連コミュニティでの自然流入を作る手法を提案。具体的に：1) ローンチ当日の投稿スケジュール（時間帯・本文テンプレ10個）、2) コメント戦略（既存人気noteへの価値ある返信テンプレ）、3) 初期の相互作用を生む返信・DM戦術、4) リード獲得策（フリープレゼントの形式と配布方法）、5) もし少額投資を許容するなら最小費用で効果的な広告案。各施策に期待効果と実行手順を明記する。','[\"初期は有料広告なしを想定（ただし代替案で少額案を提示可）\", \"スパム的手法や規約違反は不可\"]','[\"ローンチ初週／初月の投稿スケジュールとサンプル文（10件）\", \"コメント／返信テンプレ集\", \"フリーマグネット設計（何を配るか、配布方法）\"]','completed',80.00,0,3,NULL,NULL,'2026-08-07 15:38:50','2026-08-07 12:15:47','2026-08-07 15:38:50'),(12,'TSK-1786072536697-11',1,NULL,NULL,7,1,'measurement_and_testing','KPI設計とA/Bテスト計画（計測・改善設計）','公開後に改善を回せるよう、計測すべきKPIと具体的なA/Bテスト計画を作る','初期KPI（PV、滞在時間、クリック率、購入率、CVR、購入単価）を確定し、各指標の測定方法（note内指標＋外部トラッキング）を提示。さらに優先度の高いA/Bテストを3件設計（例：タイトルA/B、サムネA/B、価格A/B）、各テストの成功判定基準（有意差ではなく実務上の閾値）、必要サンプルサイズの目安、テスト実行手順と改善アクションのフローを提示してください。','[\"noteの計測制約を踏まえた現実的な設計\", \"初期は定量より定性的な仮説検証を重視\"]','[\"KPI一覧と測定方法\", \"3つのA/Bテスト設計書（目的・仮説・成功基準・手順）\", \"改善サイクルの実行フロー（チェックリスト）\"]','completed',80.00,0,3,NULL,NULL,'2026-08-07 15:51:37','2026-08-07 12:15:47','2026-08-07 15:51:37'),(13,'TSK-1786072536697-12',1,NULL,NULL,1,NULL,'project_management','再現可能なSOPと自動化チェックリスト（組織化）','本プロセスを誰でも再現できる形にまとめ、将来的な自動化ポイントを明示する','これまでの成果物を統合し、最短でMVP→販売→改善を回すためのSOPを作成してください。内容：1) フェーズ別チェックリスト（調査→企画→制作→公開→計測→改善）、2) 各工程で使うテンプレ（プロンプト・チェックリスト・提出フォーマット）、3) 自動化可能なポイント（自動投稿、テンプレ流用、レポート自動生成）と推奨ツール、4) 想定スケジュール（4〜8週間）と必要リソース。最後に次回改善点の優先順位を3つ提示。','[\"実行を担当するのは個人（1人）でも回せる設計にする\", \"現状のAIツール前提の自動化案を含める\"]','[\"SOP文書（段階別チェックリスト＋テンプレ集）\", \"自動化チェックリスト（ツール／手順）\", \"次回改善の優先順位3点\"]','pending',85.00,0,3,NULL,NULL,NULL,'2026-08-07 12:15:47','2026-08-07 12:15:47');
